using System.Reflection;
using System.Text.Json;
using CYInvoice.Core;
using CYInvoice.Core.Amego;
using CYInvoice.Core.Cloud;

internal static class AllowanceDecimalContractTests
{
    // Generated by the real desktop draft builder. Synthetic data only.
    public static string ExportFixtures()
    {
        var invoice = new InvoiceRecord {
            InvoiceNumber="AB12345678", InvoiceDate="20261015", Environment="test",
            BuyerIdentifier="0000000000", BuyerName="Synthetic decimal contract buyer"
        };
        AllowanceProductItem Item(decimal quantity, decimal price, decimal amount, decimal tax) => new() {
            OriginalInvoiceNumber=invoice.InvoiceNumber, OriginalInvoiceDate=20261015,
            OriginalDescription="Synthetic decimal contract item", Quantity=quantity,
            UnitPrice=price, Amount=amount, Tax=tax, TaxType=1
        };
        CloudAllowanceDraft Draft(string suffix, long gross, params AllowanceProductItem[] items) =>
            CloudAllowanceSubmissionService.BuildDraft("application_decimal_contract_"+suffix,invoice,
                new DateOnly(2026,10,16),gross,"Synthetic decimal contract",items);
        return JsonSerializer.Serialize(new[] {
            Draft("discount",248,Item(1,314.2857143m,314,16),Item(1,-78.0952381m,-78,-4)),
            Draft("quantity",63,Item(0.5m,120m,60,3)),
            Draft("precision",94576,Item(0.0000001m,900719925474.0000001m,90072,4504))
        });
    }

    public static void Run()
    {
        using var resource=Assembly.GetExecutingAssembly().GetManifestResourceStream("AllowanceDecimalContract.json")
            ?? throw new InvalidOperationException("Missing synthetic desktop decimal fixture");
        using var fixture=JsonDocument.Parse(resource);
        using var actual=JsonDocument.Parse(ExportFixtures());
        if(!JsonElement.DeepEquals(fixture.RootElement,actual.RootElement))
            throw new InvalidOperationException("Cloud fixture no longer matches the actual desktop BuildDraft output");
        var precise=actual.RootElement[2].GetProperty("UnnumberedTemplateJson").GetString()!;
        if(!precise.Contains("900719925474.0000001",StringComparison.Ordinal)||
           !precise.Contains("0.0000001",StringComparison.Ordinal))
            throw new InvalidOperationException("Desktop decimal tokens must remain exact JSON numbers");
    }
}
